                /** @description LOWEST nightly price in MAJOR currency units, not cents. `150` means 150.00. Must be <= maxPrice. */
                minPrice?: number;
                /** @description Highest nightly price in MAJOR currency units, not cents. */
                maxPrice?: number;
                /** @description Comma-separated amenity slugs, ANDed: `wifi,pool` returns only hotels with both. Slugs are lowercase: wifi, pool, breakfast, pets, ac, workspace, gym, spa, restaurant, bar, parking, shuttle. */
                amenities?: string;
                /** @description `recommended` (default) is star rating then name. `rating_desc` puts hotels with no reviews last, because a null average is not the best rating. */
                sort?: "recommended" | "price_asc" | "price_desc" | "rating_desc" | "name_asc";
                /** @description 1-based page number. */
                page?: number;
                /** @description Items per page, 1-50. */
                pageSize?: number;
